-- 2.20 (ITH-209): IT procurement as a Service Request category (not an incident — nothing is broken; it is a request
-- to buy). Sub-categories by what is bought, each with its own questions and purchase checklist; manager approval through
-- the hardware workflow. Added only if the client has no "IT Procurement" category yet. Re-runnable.
BEGIN;
INSERT INTO public.itsm_catalog (ticket_type, category, subcategory, team_id, resolution_days, sort_order, is_active, updated_by, form_fields, tasks)
SELECT 'Service Request', 'IT Procurement', NULL,
  coalesce((SELECT team_id FROM public.itsm_catalog WHERE ticket_type = 'Service Request' AND category = 'Hardware Request' AND subcategory IS NULL LIMIT 1),
           (SELECT id FROM public.itsm_teams WHERE lower(name) = 'it helpdesk' AND is_active LIMIT 1)),
  15, 5, true, 'system', '[{"key": "item", "label": "What to buy (item / product)", "type": "text", "required": true}, {"key": "qty", "label": "Quantity", "type": "number", "required": true}, {"key": "purpose", "label": "New, replacement or additional", "type": "select", "options": ["New", "Replacement", "Additional"], "required": true}, {"key": "forWhom", "label": "For whom (if for a person)", "type": "user"}, {"key": "reason", "label": "Business reason", "type": "textarea", "required": true}, {"key": "cost", "label": "Estimated cost (₹, if known)", "type": "number"}, {"key": "needBy", "label": "Needed by", "type": "date"}, {"key": "vendor", "label": "Preferred vendor / quote reference", "type": "text"}]'::jsonb, '["Check stock first (re-use if available)", "Get quotations (2–3 vendors)", "Budget / finance approval", "Raise the purchase order", "Receive and check the delivery", "Add to the Asset Registry (asset tag, serial, warranty, invoice)", "Hand over to the requester"]'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.itsm_catalog WHERE ticket_type = 'Service Request' AND lower(category) = 'it procurement');

INSERT INTO public.itsm_catalog (ticket_type, category, subcategory, team_id, sort_order, is_active, updated_by, form_fields, tasks)
SELECT 'Service Request', 'IT Procurement', v.sub, NULL::integer, v.n, true, 'system', v.fields, v.tasks
FROM (VALUES
 ('Laptop / Desktop', '[{"key": "item", "label": "What to buy (item / product)", "type": "text", "required": true}, {"key": "qty", "label": "Quantity", "type": "number", "required": true}, {"key": "purpose", "label": "New, replacement or additional", "type": "select", "options": ["New", "Replacement", "Additional"], "required": true}, {"key": "forWhom", "label": "For whom (if for a person)", "type": "user"}, {"key": "reason", "label": "Business reason", "type": "textarea", "required": true}, {"key": "cost", "label": "Estimated cost (₹, if known)", "type": "number"}, {"key": "needBy", "label": "Needed by", "type": "date"}, {"key": "vendor", "label": "Preferred vendor / quote reference", "type": "text"}, {"key": "config", "label": "Configuration", "type": "select", "options": ["Standard", "Developer / high performance", "Executive"], "required": true}]'::jsonb, '["Check stock first (re-use if available)", "Get quotations (2–3 vendors)", "Budget / finance approval", "Raise the purchase order", "Receive and check the delivery", "Add to the Asset Registry (asset tag, serial, warranty, invoice)", "Hand over to the requester"]'::jsonb, 1),
 ('Monitor & accessories', '[{"key": "item", "label": "What to buy (item / product)", "type": "text", "required": true}, {"key": "qty", "label": "Quantity", "type": "number", "required": true}, {"key": "purpose", "label": "New, replacement or additional", "type": "select", "options": ["New", "Replacement", "Additional"], "required": true}, {"key": "forWhom", "label": "For whom (if for a person)", "type": "user"}, {"key": "reason", "label": "Business reason", "type": "textarea", "required": true}, {"key": "cost", "label": "Estimated cost (₹, if known)", "type": "number"}, {"key": "needBy", "label": "Needed by", "type": "date"}, {"key": "vendor", "label": "Preferred vendor / quote reference", "type": "text"}, {"key": "accessory", "label": "Type", "type": "select", "options": ["Monitor", "Keyboard / mouse", "Headset", "Docking station", "Webcam", "Bag", "Other"], "required": true}]'::jsonb, '["Check stock first (re-use if available)", "Get quotations (2–3 vendors)", "Budget / finance approval", "Raise the purchase order", "Receive and check the delivery", "Add to the Asset Registry (asset tag, serial, warranty, invoice)", "Hand over to the requester"]'::jsonb, 2),
 ('Mobile phone / tablet', '[{"key": "item", "label": "What to buy (item / product)", "type": "text", "required": true}, {"key": "qty", "label": "Quantity", "type": "number", "required": true}, {"key": "purpose", "label": "New, replacement or additional", "type": "select", "options": ["New", "Replacement", "Additional"], "required": true}, {"key": "forWhom", "label": "For whom (if for a person)", "type": "user"}, {"key": "reason", "label": "Business reason", "type": "textarea", "required": true}, {"key": "cost", "label": "Estimated cost (₹, if known)", "type": "number"}, {"key": "needBy", "label": "Needed by", "type": "date"}, {"key": "vendor", "label": "Preferred vendor / quote reference", "type": "text"}, {"key": "plan", "label": "SIM / data plan needed", "type": "yesno"}]'::jsonb, '["Check stock first (re-use if available)", "Get quotations (2–3 vendors)", "Budget / finance approval", "Raise the purchase order", "Receive and check the delivery", "Add to the Asset Registry (asset tag, serial, warranty, invoice)", "Hand over to the requester"]'::jsonb, 3),
 ('Printer / scanner', '[{"key": "item", "label": "What to buy (item / product)", "type": "text", "required": true}, {"key": "qty", "label": "Quantity", "type": "number", "required": true}, {"key": "purpose", "label": "New, replacement or additional", "type": "select", "options": ["New", "Replacement", "Additional"], "required": true}, {"key": "forWhom", "label": "For whom (if for a person)", "type": "user"}, {"key": "reason", "label": "Business reason", "type": "textarea", "required": true}, {"key": "cost", "label": "Estimated cost (₹, if known)", "type": "number"}, {"key": "needBy", "label": "Needed by", "type": "date"}, {"key": "vendor", "label": "Preferred vendor / quote reference", "type": "text"}, {"key": "location", "label": "Location / floor", "type": "text", "required": true}]'::jsonb, '["Check stock first (re-use if available)", "Get quotations (2–3 vendors)", "Budget / finance approval", "Raise the purchase order", "Receive and check the delivery", "Add to the Asset Registry (asset tag, serial, warranty, invoice)", "Hand over to the requester"]'::jsonb, 4),
 ('Network / server / storage hardware', '[{"key": "item", "label": "What to buy (item / product)", "type": "text", "required": true}, {"key": "qty", "label": "Quantity", "type": "number", "required": true}, {"key": "purpose", "label": "New, replacement or additional", "type": "select", "options": ["New", "Replacement", "Additional"], "required": true}, {"key": "forWhom", "label": "For whom (if for a person)", "type": "user"}, {"key": "reason", "label": "Business reason", "type": "textarea", "required": true}, {"key": "cost", "label": "Estimated cost (₹, if known)", "type": "number"}, {"key": "needBy", "label": "Needed by", "type": "date"}, {"key": "vendor", "label": "Preferred vendor / quote reference", "type": "text"}, {"key": "site", "label": "Site / data centre / cloud region", "type": "text", "required": true}]'::jsonb, '["Check stock first (re-use if available)", "Get quotations (2–3 vendors)", "Budget / finance approval", "Raise the purchase order", "Receive and check the delivery", "Add to the Asset Registry (asset tag, serial, warranty, invoice)", "Hand over to the requester"]'::jsonb, 5),
 ('Software licence / subscription', '[{"key": "item", "label": "What to buy (item / product)", "type": "text", "required": true}, {"key": "qty", "label": "Quantity", "type": "number", "required": true}, {"key": "purpose", "label": "New, replacement or additional", "type": "select", "options": ["New", "Replacement", "Additional"], "required": true}, {"key": "forWhom", "label": "For whom (if for a person)", "type": "user"}, {"key": "reason", "label": "Business reason", "type": "textarea", "required": true}, {"key": "cost", "label": "Estimated cost (₹, if known)", "type": "number"}, {"key": "needBy", "label": "Needed by", "type": "date"}, {"key": "vendor", "label": "Preferred vendor / quote reference", "type": "text"}, {"key": "users", "label": "Number of users / seats", "type": "number", "required": true}, {"key": "term", "label": "Term", "type": "select", "options": ["Monthly", "Yearly", "Perpetual"], "required": true}]'::jsonb, '["Check existing licences first", "Get the quotation", "Budget / finance approval", "Raise the purchase order", "Record the licence / subscription (Licences: seats, expiry, cost)", "Assign it and confirm with the requester"]'::jsonb, 6),
 ('Cloud / SaaS service', '[{"key": "item", "label": "What to buy (item / product)", "type": "text", "required": true}, {"key": "qty", "label": "Quantity", "type": "number", "required": true}, {"key": "purpose", "label": "New, replacement or additional", "type": "select", "options": ["New", "Replacement", "Additional"], "required": true}, {"key": "forWhom", "label": "For whom (if for a person)", "type": "user"}, {"key": "reason", "label": "Business reason", "type": "textarea", "required": true}, {"key": "cost", "label": "Estimated cost (₹, if known)", "type": "number"}, {"key": "needBy", "label": "Needed by", "type": "date"}, {"key": "vendor", "label": "Preferred vendor / quote reference", "type": "text"}, {"key": "data", "label": "Will company or client data be stored in it?", "type": "yesno", "required": true}]'::jsonb, '["Get the quotation / proposal", "Security & data-protection review of the vendor", "Budget / finance approval", "Contract / purchase order", "Record in Contracts & AMC (renewal date, cost)", "Confirm with the requester"]'::jsonb, 7),
 ('AMC / support renewal', '[{"key": "item", "label": "What to buy (item / product)", "type": "text", "required": true}, {"key": "qty", "label": "Quantity", "type": "number", "required": true}, {"key": "purpose", "label": "New, replacement or additional", "type": "select", "options": ["New", "Replacement", "Additional"], "required": true}, {"key": "forWhom", "label": "For whom (if for a person)", "type": "user"}, {"key": "reason", "label": "Business reason", "type": "textarea", "required": true}, {"key": "cost", "label": "Estimated cost (₹, if known)", "type": "number"}, {"key": "needBy", "label": "Needed by", "type": "date"}, {"key": "vendor", "label": "Preferred vendor / quote reference", "type": "text"}, {"key": "contract", "label": "Existing contract / vendor", "type": "text", "required": true}, {"key": "expiry", "label": "Current expiry date", "type": "date"}]'::jsonb, '["Get the quotation / proposal", "Security & data-protection review of the vendor", "Budget / finance approval", "Contract / purchase order", "Record in Contracts & AMC (renewal date, cost)", "Confirm with the requester"]'::jsonb, 8),
 ('Consumables (toner, cables, batteries)', '[{"key": "item", "label": "What to buy (item / product)", "type": "text", "required": true}, {"key": "qty", "label": "Quantity", "type": "number", "required": true}, {"key": "purpose", "label": "New, replacement or additional", "type": "select", "options": ["New", "Replacement", "Additional"], "required": true}, {"key": "forWhom", "label": "For whom (if for a person)", "type": "user"}, {"key": "reason", "label": "Business reason", "type": "textarea", "required": true}, {"key": "cost", "label": "Estimated cost (₹, if known)", "type": "number"}, {"key": "needBy", "label": "Needed by", "type": "date"}, {"key": "vendor", "label": "Preferred vendor / quote reference", "type": "text"}]'::jsonb, '["Check stock first", "Raise the purchase order", "Receive and hand over"]'::jsonb, 9),
 ('Others', '[{"key": "item", "label": "What to buy (item / product)", "type": "text", "required": true}, {"key": "qty", "label": "Quantity", "type": "number", "required": true}, {"key": "purpose", "label": "New, replacement or additional", "type": "select", "options": ["New", "Replacement", "Additional"], "required": true}, {"key": "forWhom", "label": "For whom (if for a person)", "type": "user"}, {"key": "reason", "label": "Business reason", "type": "textarea", "required": true}, {"key": "cost", "label": "Estimated cost (₹, if known)", "type": "number"}, {"key": "needBy", "label": "Needed by", "type": "date"}, {"key": "vendor", "label": "Preferred vendor / quote reference", "type": "text"}]'::jsonb, '["Check stock first (re-use if available)", "Get quotations (2–3 vendors)", "Budget / finance approval", "Raise the purchase order", "Receive and check the delivery", "Add to the Asset Registry (asset tag, serial, warranty, invoice)", "Hand over to the requester"]'::jsonb, 10)
) v(sub, fields, tasks, n)
WHERE NOT EXISTS (SELECT 1 FROM public.itsm_catalog x WHERE x.ticket_type = 'Service Request' AND lower(x.category) = 'it procurement' AND x.subcategory IS NOT NULL AND x.updated_by IS DISTINCT FROM 'system')
  AND NOT EXISTS (SELECT 1 FROM public.itsm_catalog x WHERE x.ticket_type = 'Service Request' AND lower(x.category) = 'it procurement' AND lower(x.subcategory) = lower(v.sub));

-- manager approval: the request goes through the hardware workflow (if that workflow exists and does not have it yet)
UPDATE public.itsm_workflows w SET match = jsonb_set(coalesce(w.match, '{}'::jsonb), '{category}', coalesce(w.match->'category', '[]'::jsonb) || '["IT Procurement"]'::jsonb)
WHERE w.ticket_type = 'request' AND w.name = 'IT hardware & accessories (manager approval)'
  AND NOT coalesce(w.match->'category', '[]'::jsonb) ? 'IT Procurement';
COMMIT;
